def std_offset(zone):
    for year in (2026, 2025, 2024):
        for month in (1, 7):
            moment = datetime(year, month, 1, tzinfo=zone)
            if not moment.dst():
                return moment.utcoffset()
    return datetime(2026, 1, 1, tzinfo=zone).utcoffset()


def to_epoch(local, zone, dst=None):
    first = local.replace(tzinfo=zone, fold=0)
    second = local.replace(tzinfo=zone, fold=1)
    a = first.timestamp()
    b = second.timestamp()
    if a == b or dst is None:
        return int(a)
    if bool(first.dst()) == dst:
        return int(a)
    if bool(second.dst()) == dst:
        return int(b)
    return int(a)


