def round_instant(instant, zone):
    offset = datetime.fromtimestamp(instant, zone).utcoffset().total_seconds()
    remainder = int(instant + offset) % 360
    if remainder >= 180:
        return instant + 360 - remainder
    return instant - remainder


def night_seconds(start, end, zone):
    if end <= start:
        return 0
    first = datetime.fromtimestamp(start, zone).date() - timedelta(days=1)
    last = datetime.fromtimestamp(end, zone).date() + timedelta(days=1)
    total = 0
    day = first
    while day <= last:
        win_start = datetime(day.year, day.month, day.day, 22, tzinfo=zone).timestamp()
        nxt = day + timedelta(days=1)
