                del punches[key]
                applied += 1
        elif action == "set":
            if key in punches:
                punches[key]["t"] = int(datetime.fromisoformat(corr["time"]).timestamp())
                applied += 1
        elif action == "add":
            if key not in existed:
                existed.add(key)
                punches[key] = {"emp": corr["employee"], "dir": corr["type"].upper(),
                                "t": int(datetime.fromisoformat(corr["time"]).timestamp())}
                applied += 1

    by_emp = {}
    for (site, pid), p in punches.items():
        if p["emp"] in employees:
            by_emp.setdefault(p["emp"], []).append((p["t"], 0 if p["dir"] == "OUT" else 1, site, pid, p["dir"]))

    stats = {e: {"shifts": 0, "paid_minutes": 0, "overtime_minutes": 0, "night_minutes": 0}
             for e in employees}
    gross = {e: Decimal(0) for e in employees}
    exceptions = {"open_shifts": 0, "orphan_outs": 0, "duplicates_dropped": 0}

    for emp, plist in by_emp.items():
        home = sites[employees[emp]][0]
        plist.sort()
        kept = []
        last = None
        for t, _, site, pid, direction in plist:
            zone = sites[site][0]
            rounded = round_instant(t, zone)
            if last is not None and last[0] == direction and t - last[1] <= 300:
                workday = datetime.fromtimestamp(rounded, home).date()
                if start <= workday <= end:
                    exceptions["duplicates_dropped"] += 1
                continue
            last = (direction, t)
            kept.append((direction, rounded, site))

        def workday_of(instant):
            return datetime.fromtimestamp(instant, home).date()

        def in_period(instant):
            return start <= workday_of(instant) <= end

        shifts = []
        pending = None
        for direction, rounded, site in kept:
            if direction == "IN":
                if pending and in_period(pending[0]):
                    exceptions["open_shifts"] += 1
                pending = (rounded, site)
            else:
                if pending and rounded - pending[0] <= 16 * 3600:
                    shifts.append((pending[0], rounded, pending[1]))
                    pending = None
                else:
                    if pending and in_period(pending[0]):
                        exceptions["open_shifts"] += 1
                    pending = None
                    if in_period(rounded):
                        exceptions["orphan_outs"] += 1
        if pending and in_period(pending[0]):
            exceptions["open_shifts"] += 1

        shifts = [s for s in shifts if in_period(s[0])]
        shifts.sort(key=lambda s: s[0])
        day_total = {}
        week_total = {}
        for s_in, s_out, site in shifts:
            zone = sites[site][0]
            worked = max(0, (s_out - s_in) // 60)
            paid = worked - 30 if worked > 360 else worked
            night = min(night_seconds(s_in, s_out, zone) // 60, paid)
            day = workday_of(s_in)
            before = day_total.get(day, 0)
            day_total[day] = before + paid
            daily_ot = max(0, before + paid - 480) - max(0, before - 480)
            week = day - timedelta(days=day.weekday())
            wbefore = week_total.get(week, 0)
            nondaily = paid - daily_ot
            week_total[week] = wbefore + nondaily
            weekly_ot = max(0, wbefore + nondaily - 2400) - max(0, wbefore - 2400)
            overtime = daily_ot + weekly_ot
            regular = paid - overtime
            rate = None
            for effective, value in rates.get(emp, []):
                if effective <= day:
                    rate = value
            if rate is None:
                rate = Decimal(0)
            pay = rate * (Decimal(regular) + Decimal("1.5") * overtime) / 60 \
                + rate * Decimal("0.15") * night / 60
            gross[emp] += pay
            st = stats[emp]
            st["shifts"] += 1
            st["paid_minutes"] += paid
            st["overtime_minutes"] += overtime
            st["night_minutes"] += night

    result_emps = {}
    totals = {"shifts": 0, "paid_minutes": 0, "overtime_minutes": 0, "night_minutes": 0}
    total_gross = Decimal(0)
    for emp in employees:
        cents = gross[emp].quantize(Decimal("0.01"), rounding=ROUND_HALF_UP)
        entry = dict(stats[emp])
        entry["gross"] = "{:.2f}".format(cents)
        result_emps[emp] = entry
        for key in totals:
            totals[key] += stats[emp][key]
        total_gross += cents
    totals["gross"] = "{:.2f}".format(total_gross)
    exceptions["corrections_applied"] = applied
    result = {
        "period": {"start": period["start"], "end": period["end"]},
        "employees": result_emps,
        "exceptions": exceptions,
        "totals": totals,
    }
    out_file.parent.mkdir(parents=True, exist_ok=True)
    out_file.write_text(json.dumps(result, indent=1))


